     1|/**
     2| * IVX Worker Access Tokens — short-lived, single-use, owner-authorized worker credentials.
     3| *
     4| * Replaces the need to store a raw Supabase owner session as a permanent Render
     5| * secret. The owner authenticates ONCE per action with their live Supabase JWT
     6| * (verified by the existing registered-owner bearer guard), and this service
     7| * mints a short-lived (5-15 minute), single-use, action + commit-SHA-bound
     8| * token. Only a SHA-256 hash of the token is ever persisted — the raw value is
     9| * returned exactly once, to the owner, at mint time, and never logged.
    10| *
    11| * The dedicated worker then presents this token (alongside its existing signed
    12| * HMAC identity — see ivx-internal-deploy-auth.ts) to consume the token
    13| * atomically. Consumption is one-time: a second presentation of the same raw
    14| * token is rejected as a replay.
    15| */
    16|import { createHash, randomBytes } from 'node:crypto';
    17|import { readDurableJson, writeDurableJson } from './ivx-durable-store';
    18|
    19|const TOKEN_STORE = 'logs/audit/worker-access-tokens/tokens.json';
    20|const MAX_STORED_TOKENS = 500;
    21|const MIN_TTL_MINUTES = 5;
    22|const MAX_TTL_MINUTES = 15;
    23|const DEFAULT_TTL_MINUTES = 10;
    24|
    25|export type WorkerAccessAction = 'GITHUB_WRITE' | 'RENDER_DEPLOY' | 'PRODUCTION_DEPLOY' | 'QA_ONLY';
    26|
    27|const ALLOWED_ACTIONS = new Set<WorkerAccessAction>(['GITHUB_WRITE', 'RENDER_DEPLOY', 'PRODUCTION_DEPLOY', 'QA_ONLY']);
    28|
    29|export type WorkerAccessTokenRecord = {
    30|  id: string;
    31|  ownerId: string;
    32|  action: WorkerAccessAction;
    33|  commitSha: string;
    34|  tokenHash: string;
    35|  workerId: string | null;
    36|  requestId: string;
    37|  issuedAt: string;
    38|  expiresAt: string;
    39|  usedAt: string | null;
    40|  revokedAt: string | null;
    41|  revokedReason: string | null;
    42|  createdAt: string;
    43|};
