    45|export type WorkerAccessTokenStore = {
    46|  readJson<T>(file: string, fallback: T): Promise<T>;
    47|  writeJson(file: string, value: unknown): Promise<void>;
    48|};
    49|
    50|const durableTokenStore: WorkerAccessTokenStore = {
    51|  readJson: readDurableJson,
    52|  writeJson: writeDurableJson,
