   164|export async function consumeWorkerAccessToken(
   165|  input: ConsumeWorkerAccessInput,
   166|  store: WorkerAccessTokenStore = durableTokenStore,
   167|): Promise<ConsumeWorkerAccessResult> {
   168|  const presentedHash = hashToken(input.rawToken);
   169|  const commitSha = input.commitSha.trim().toLowerCase();
   170|  const tokens = await store.readJson<WorkerAccessTokenRecord[]>(TOKEN_STORE, []);
   171|  const index = tokens.findIndex((token) => token.tokenHash === presentedHash);
   172|  const record = index >= 0 ? tokens[index] : null;
